VALUES ('f_c612c0e68a27b3330eb46a', 'Runway & shutdown cash notes', 'application/vnd.google-apps.document', '["d_63fffeb4fab5233ed5bb73"]', 'leonard.hayes@harmonygames.co', '["frederick.stone@harmonygames.co", "arthur.blake@harmonygames.co"]', '[{"email": "frederick.stone@harmonygames.co", "role": "reader"}, {"email": "arthur.blake@harmonygames.co", "role": "reader"}]', 'private', '["leonard.hayes@harmonygames.co"]', '2025-09-30T17:48:00Z', '2025-09-25T16:12:00Z', false, false);
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_c612c0e68a27b3330eb46a', 'Runway & shutdown cash notes', 'leonard.hayes@harmonygames.co', '["frederick.stone@harmonygames.co", "arthur.blake@harmonygames.co"]', 'private', E'Runway & shutdown cash notes\nLeonard - started Sep 25, updated Sep 30\n\nWhere we are\nAbout two months before we have to let people go unless the bridge or an engine deal lands. Keep enough aside to close the company properly (legal, final payroll, state filings). No new commitments without the three of us agreeing.\n\nShutdown reserve\nLegal: ask our lawyer for a quote to wind down. Final payroll and accrued PTO through Gusto. Delaware franchise tax and the annual report are due in March whatever happens.\n\nMoney still moving (for the cuts)\nAn account still has money moving if anything was spent, billed or paid out on it in September 2025, or a campaign on it is still switched on. Ad revenue paid to us counts (the warehouse has it by network and month). Spend or a charge the vendor has agreed in writing to drop doesn''t count. Heads up on the warehouse: the spend tables have no Meta spend after April and no Unity cost at all, so for spend go by the receipts and whether the campaign is on. The finance ledger lumps the ad network payouts together under AppLovin/MAX and runs a month behind, so for what was paid to us use the ad revenue numbers by network, not the ledger.\n\nCuts\nFred: marketing, UA and socials. Arthur: engineering, stores and data tools. I''ll take software subscriptions and the card.\n\nOpen\nBridge: still talking to two funds. Engine: NCsoft is slow, follow up next week.\n', '[{"start": 0, "end": 29, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 29, "end": 71, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 71, "end": 84, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 84, "end": 317, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 317, "end": 334, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 334, "end": 508, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 508, "end": 542, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 542, "end": 1182, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 1182, "end": 1187, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 1187, "end": 1312, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 1312, "end": 1317, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 1317, "end": 1398, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '50f9b14a86', 'f_c612c0e68a27b3330eb46a', '2025-09-25T16:12:00Z', '2025-09-30T17:48:00Z');
