INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('1ecb6ef5fa9552cc9fbd4c60f4672909', '1759266627.118342', 'C07C2866011', 'message', 'EMPLOYEE_0025_SLACK_ID', 'sweep''s in the drive folder. only youtube and tiktok are on fred alone, everything else already has two of us on it', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-30T21:10:27.118342Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('02847a3cc740c9b657d75f26c3750854', '1759272012.507134', 'D05S58U4SAK', 'message', 'EMPLOYEE_0038_SLACK_ID', 'ok after the tiktok/youtube mess I want every marketing + UA account you''re on sorted before we start letting people go. one row per account: who actually holds it, whether money is still moving on it, and what we do with it. arthur''s handover rules are on the Harmony Games board, they decide the action. arthur''s sweep from today is the list. save the register in the Company Ops folder and reply here with how many you''ve marked TRANSFER and anything an outsider still has access to', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-30T22:40:12.507134Z', '{}');
INSERT INTO trello.trello_cards (id, name, "idBoard", "idList", "desc", pos, closed, due, "dueComplete", "idMembers_json", "idLabels_json", "idShort", "shortLink", "shortUrl", url, "dateLastActivity", cover_json, badges_json)
VALUES ('68dc406c7b0d03e53b334bab', 'Account handover rules - marketing, UA & socials', '640643a3fd8f3ca308d9318e', '640643a3fd8f3ca308d93195', E'For Fred''s accounts before the cuts. These replace the old Company Accounts & Access page on Confluence for marketing.\n\n1. Scope: every marketing, UA, ad-monetization and social account in today''s sweep folder that has Fred on it in any role. Store accounts (App Store Connect, Play Console) and data tools (Singular, Metabase) are on the engineering card. Networks we only reach as bidders inside MAX are not separate accounts here. An account that was deleted or deactivated before the sweep is off the list.\n2. Holder = Owner, Admin or Super admin. Managers, standard users, analysts, advertisers, content admins, pending invites and anyone logging in with someone else''s password don''t count.\n3. A company holder is a holder whose login is a person''s harmonygames.co address. Personal addresses and group inboxes aren''t company holders. A personal address isn''t outside access either.\n4. Class: OUTSIDE ACCESS if an agency, contractor or partner business still has admin or partner admin access. Otherwise SINGLE if fewer than two company holders, COMPANY-HELD if two or more.\n5. Action: OUTSIDE ACCESS -> REVOKE. Otherwise no money moving -> CLOSE. Otherwise SINGLE -> TRANSFER (Leonard is added as an owner), COMPANY-HELD -> KEEP. Money moving is whatever Leonard defined it as for the cuts.\n6. Register columns: account, company holders, class, money moving (Y/N), action.\n7. Socials that need a transfer go as a checklist on Fred''s "Lock up social handles and domain?" card on the UA/BD board. Don''t open a new card.', 1327104.0, false, NULL, false, '[]', '[]', 456, NULL, NULL, 'https://PERSON_6092_TRELLO_USERNAME.com/c/OSVNJujs/456-account-handover-rules-marketing-ua-socials', '2025-09-30T21:58:44Z', NULL, '{"attachments": 0, "attachmentsByType": {"trello": {"board": 0, "card": 0}}, "checkItems": 0, "checkItemsChecked": 0, "checkItemsEarliestDue": null, "comments": 1, "description": true, "due": null, "dueComplete": false, "externalSource": null, "fogbugz": "", "lastUpdatedByAi": false, "location": false, "maliciousAttachments": 0, "start": null, "votes": 0}');
