INSERT INTO trello.trello_cards (id, name, "idBoard", "idList", "desc", pos, closed, due, "dueComplete", "idMembers_json", "idLabels_json", "idShort", "shortLink", "shortUrl", url, "dateLastActivity", cover_json, badges_json)
VALUES ('68dc42f3095ad95194a711ae', 'Account handover rules - engineering, stores & data tools', '640643a3fd8f3ca308d9318e', '640643a3fd8f3ca308d93195', E'My list, not Fred''s: GitHub, AWS, Unity Cloud Build, App Store Connect, Play Console, Singular, Metabase.\n\nOne Owner is fine as long as the break-glass login is in 1Password. Nothing on this list gets closed before the stores are sorted - mark each one KEEP or MOVE (to the new org).', 1392640.0, false, NULL, false, '[]', '[]', 457, NULL, NULL, 'https://PERSON_6092_TRELLO_USERNAME.com/c/QGk3Bx3U/457-account-handover-rules-engineering-stores-data-tools', '2025-09-30T20:52:03Z', NULL, '{"attachments": 0, "attachmentsByType": {"trello": {"board": 0, "card": 0}}, "checkItems": 0, "checkItemsChecked": 0, "checkItemsEarliestDue": null, "comments": 0, "description": true, "due": null, "dueComplete": false, "externalSource": null, "fogbugz": "", "lastUpdatedByAi": false, "location": false, "maliciousAttachments": 0, "start": null, "votes": 0}');
