INSERT INTO confluence.confluence_pages (id, space_id, parent_id, title, body, body_format, status, version, author_id, created_at, updated_at)
VALUES ('page_company_accounts_access', 'space_COMPANY', 'page_company_home', 'Company Accounts & Access', '<p>Every external account the company uses needs one named owner and one backup admin. When someone leaves, the backup takes over the account; we don''t close accounts that might be useful later.</p><h2>What counts as an account</h2><ul><li>App stores (App Store Connect, Google Play Console)</li><li>Ad networks and ad accounts (Meta, Google Ads, Unity Ads, AppLovin)</li><li>Analytics and attribution tools</li><li>Social channels (YouTube, LinkedIn, TikTok)</li><li>Cloud and source control (AWS, GitHub)</li></ul><h2>Owner and backup</h2><p>The owner is the person who uses the account day to day. The backup is one of the founders with admin rights, so we can always get in if the owner is out. Shared logins go in the Company vault in 1Password, never in Slack or email.</p><h2>When someone leaves</h2><ol><li>The backup takes over as owner the same day.</li><li>Remove the leaver from every account they had a seat on and rotate any shared password.</li><li>Pick a new backup.</li></ol><p>Agencies and contractors get the narrowest role the platform offers and are removed when the engagement ends. Questions to Leonard.</p>', 'storage', 'current', 1, 'user_EMPLOYEE_0038', '2024-03-12T16:20:00Z', '2024-03-12T16:20:00Z');
INSERT INTO confluence.confluence_page_versions (id, page_id, number, title, body, author_id, message, created_at)
VALUES ('ver_ffb23fbfca7fff13209da81776386b49', 'page_company_accounts_access', 1, 'Company Accounts & Access', '<p>Every external account the company uses needs one named owner and one backup admin. When someone leaves, the backup takes over the account; we don''t close accounts that might be useful later.</p><h2>What counts as an account</h2><ul><li>App stores (App Store Connect, Google Play Console)</li><li>Ad networks and ad accounts (Meta, Google Ads, Unity Ads, AppLovin)</li><li>Analytics and attribution tools</li><li>Social channels (YouTube, LinkedIn, TikTok)</li><li>Cloud and source control (AWS, GitHub)</li></ul><h2>Owner and backup</h2><p>The owner is the person who uses the account day to day. The backup is one of the founders with admin rights, so we can always get in if the owner is out. Shared logins go in the Company vault in 1Password, never in Slack or email.</p><h2>When someone leaves</h2><ol><li>The backup takes over as owner the same day.</li><li>Remove the leaver from every account they had a seat on and rotate any shared password.</li><li>Pick a new backup.</li></ol><p>Agencies and contractors get the narrowest role the platform offers and are removed when the engagement ends. Questions to Leonard.</p>', 'user_EMPLOYEE_0038', NULL, '2024-03-12T16:20:00Z');
